/// Everything the app's Security card draws. Every field is derived from a
/// `cscli` call at request time — nothing is stored — so the numbers are live,
/// and a host whose CrowdSec is missing or broken comes back with `present`
/// false and the rest zeroed rather than as an error (the card then says the
/// protection is not in place, which is the true and useful thing to show).
public nonisolated struct Gryonixnexusd_V1_SecurityStatus: Sendable {
  // SwiftProtobuf.Message conformance is added in an extension below. See the
  // `Message` and `Message+*Additions` files in the SwiftProtobuf library for
  // methods supported on all messages.

  /// cscli is on the host AND `/etc/crowdsec/config.yaml` exists — the same
  /// "configured, not merely unpacked" test the installer uses, because a
  /// failed postinst leaves the binary answering and nothing behind it.
  public var present: Bool = false

  public var engineRunning: Bool = false

  public var bouncerRunning: Bool = false

  /// e.g. "v1.8.0". Empty when it could not be read.
  public var engineVersion: String = String()

  /// Local alerts CrowdSec raised in the last 24 hours (attacks it saw on THIS
  /// host's journals — distinct from the community blocklist below).
  public var alerts24H: UInt32 = 0

  /// Addresses this host is actively blocking right now off its own decisions.
  public var localBans: UInt32 = 0

  /// Size of the community blocklist the bouncer is also enforcing — addresses
  /// other CrowdSec installations reported, dropped here before they ever
  /// reach a service. Read from the bouncer's own metrics.
  public var communityBlocklistIps: UInt32 = 0

  /// Packets the bouncer has dropped since it started, across every source.
  public var packetsDropped: UInt64 = 0

  /// The scenarios that have fired most on this host, all-time, most first.
  public var topScenarios: [Gryonixnexusd_V1_SecurityScenario] = []

  /// The most recent attacks, newest first — for the "caught these" list.
  public var recentBans: [Gryonixnexusd_V1_SecurityBan] = []

  public var unknownFields = SwiftProtobuf.UnknownStorage()

  public init() {}
}

