/// What this host's sshd accepts right now, as sshd itself resolved it.
public nonisolated struct Gryonixnexusd_V1_SshPasswordState: Sendable {
  // SwiftProtobuf.Message conformance is added in an extension below. See the
  // `Message` and `Message+*Additions` files in the SwiftProtobuf library for
  // methods supported on all messages.

  /// sshd accepts passwords (either PasswordAuthentication or the
  /// keyboard-interactive route PAM answers through). Meaningless unless
  /// `known` — a host that could not be asked answers false for both.
  public var passwordLoginOpen: Bool = false

  /// sshd answered `sshd -T`, so the field above is a reading rather than a
  /// guess. A file on disk is not an answer about a running daemon: a cloud
  /// image's own `50-cloud-init.conf` outranks a drop-in numbered above it, and
  /// the merged configuration is the only place that shows.
  public var known: Bool = false

  /// The app's key is in `login_user`'s `authorized_keys` — the one condition
  /// under which closing is allowed at all.
  public var appKeyPresent: Bool = false

  /// This product's drop-in is on disk. Distinct from `password_login_open`:
  /// present-and-outranked is the failure mode the numbering exists to prevent,
  /// and it is only visible as these two disagreeing.
  public var dropInPresent: Bool = false

  /// This host has an sshd to ask.
  public var sshdPresent: Bool = false

  /// The account that was actually checked, resolved here when the request left
  /// it empty — the app shows it, because "which account" is precisely what is
  /// ambiguous from the client side.
  public var loginUser: String = String()

  /// One sentence for the owner about what just happened, in the same words the
  /// install log uses. Empty on a plain read.
  public var detail: String = String()

  public var unknownFields = SwiftProtobuf.UnknownStorage()

